// Paddle v2 TypeScript definitions
interface PaddleEventData {
	name: string;
	data: any;
}

interface PaddleInitializeOptions {
	token: string;
	eventCallback?: (data: PaddleEventData) => void;
	pwCustomer?: {
		id?: string;
	};
	settings?: {
		allowLogout?: boolean;
		locale?: string;
		theme?: string;
		variant?: string;
	};
}

interface PaddleCheckoutItem {
