		id?: string;
	};
	address?: {
		countryCode?: string;
		postcode?: string;
	};
	customData?: Record<string, any>;
}

interface Paddle {
	Initialize: (options: PaddleInitializeOptions) => void;
	Environment: {
		set: (environment: string) => void;
	};
	Checkout: {
		open: (options: PaddleCheckoutOptions) => void;
		close: () => void;
	};
	Update: (options: Partial<PaddleInitializeOptions>) => void;
}

